def create_document(filename, title=None, author=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_full_path(p):
        if not isinstance(p, str):
            return None
        s = p.strip()
        if not s:
            return ""
        s = s.replace("\\", "/")
        # collapse repeated slashes
        s = re.sub(r"/{2,}", "/", s)
        # remove trailing slash unless it's root
        if len(s) > 1 and s.endswith("/"):
            s = s[:-1]
        # resolve '.' segments cheaply
        parts = []
        abs_like = s.startswith("/")
        for seg in s.split("/"):
            if seg == "" and abs_like:
                continue
            if seg == "." or seg == "":
                continue
            if seg == "..":
                if parts:
                    parts.pop()
                continue
            parts.append(seg)
        s2 = ("/" if abs_like else "") + "/".join(parts)
        if s2 == "":
            s2 = "/"
        return s2

    def _ensure_docx(name):
        if not isinstance(name, str):
            return None
        s = name.strip()
        if not s:
            return ""
        if not s.lower().endswith(".docx"):
            s = s + ".docx"
        return s

    t0 = time.time()
    documents = _load("documents.json")
    blocks = _load("document_blocks.json")
    spans = _load("text_spans.json")
    styles = _load("styles.json")
    notes = _load("notes.json")
    table_formats = _load("table_formats.json")

    # Validate inputs
    if not isinstance(filename, str):
        return _err("VALIDATION_ERROR", "filename must be a string")
    if title is not None and not isinstance(title, str):
        return _err("VALIDATION_ERROR", "title must be a string or null")
    if author is not None and not isinstance(author, str):
        return _err("VALIDATION_ERROR", "author must be a string or null")

    fn = _ensure_docx(filename)
    if fn is None or fn == "":
        return _err("VALIDATION_ERROR", "filename is empty/invalid")

    full_path = _norm_full_path(fn)
    if full_path in (None, "", "/"):
        return _err("VALIDATION_ERROR", "filename is empty/invalid")

    base = os.path.basename(full_path)
    dirp = os.path.dirname(full_path).replace("\\", "/")
    if dirp == "":
        dirp = "/"

    # filename must end with .docx for active
    if not base.lower().endswith(".docx"):
        return _err("VALIDATION_ERROR", "filename must end with '.docx'")

    # uniqueness
    for d in documents:
        if d.get("full_path") == full_path:
            return _err("CONFLICT", "A document with the same filename already exists", full_path=full_path)

    # create id
    ts = int(time.time() * 1000)
    seed = f"doc:{full_path}:{ts}".encode("utf-8")
    doc_id = "doc_" + hashlib.sha256(seed).hexdigest()[:24]
    # ensure uniqueness if collision (extremely unlikely)
    existing_ids = {d.get("id") for d in documents if isinstance(d, dict)}
    if doc_id in existing_ids:
        doc_id = "doc_" + hashlib.sha256(seed + b":1").hexdigest()[:24]

    now = _now_iso()
    row = {
        "id": doc_id,
        "directory": dirp,
        "filename": base,
        "full_path": full_path,
        "title": title,
        "author": author,
        "status": "active",
        "content_version": 1,
        "file_sha256": None,
        "file_size_bytes": None,
        "protected_password_hash": None,
        "protection_algorithm": None,
        "last_indexed_at": None,
        "cached_full_text": None,
        "cached_outline": None,
        "created_at": now,
        "updated_at": now,
    }

    # Persist
    documents.append(row)
    _save("documents.json", documents)

    # Return created metadata
    return {
        "document": {
            "id": row["id"],
            "directory": row["directory"],
            "filename": row["filename"],
            "full_path": row["full_path"],
            "title": row["title"],
            "author": row["author"],
            "status": row["status"],
            "content_version": row["content_version"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        }
    }

def get_document_info(filename, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "get_document_info"

    def _log(status, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        if "\x00" in s or re.match(r"^[a-zA-Z]+://", s):
            return None
        s = re.sub(r"/+", "/", s)
        if s.startswith("./"):
            s = s[2:]
        if not s.lower().endswith(".docx"):
            s += ".docx"
        return s

    def _cands(norm_full):
        if not norm_full:
            return []
        xs = [norm_full]
        if norm_full.startswith("/"):
            xs.append(norm_full.lstrip("/"))
        else:
            xs.append("/" + norm_full)
        out, seen = [], set()
        for x in xs:
            if x not in seen:
                seen.add(x)
                out.append(x)
        return out

    def _find_doc(docs, norm_full):
        for c in _cands(norm_full):
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    try:
        full_path = _norm_docx_full_path(filename)
        if full_path is None:
            _log("error", "VALIDATION_ERROR", {"field": "filename"})
            return _err("VALIDATION_ERROR", "filename must be a non-empty string (.docx will be appended if missing)")

        docs = _load("documents.json")
        if not isinstance(docs, list):
            docs = []
        doc = _find_doc(docs, full_path)
        if not doc:
            _log("error", "NOT_FOUND", {"filename": full_path})
            return _err("NOT_FOUND", "document not found", filename=full_path)
        if doc.get("status") == "deleted":
            _log("error", "NOT_FOUND", {"filename": full_path})
            return _err("NOT_FOUND", "document not found", filename=full_path)

        doc_id = doc.get("id")
        blocks = _load("document_blocks.json")
        spans = _load("text_spans.json")
        styles = _load("styles.json")
        notes = _load("notes.json")
        table_formats = _load("table_formats.json")
        if not isinstance(blocks, list): blocks = []
        if not isinstance(spans, list): spans = []
        if not isinstance(styles, list): styles = []
        if not isinstance(notes, list): notes = []
        if not isinstance(table_formats, list): table_formats = []

        blocks_doc = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc_id]
        active_blocks = [b for b in blocks_doc if b.get("status") == "active"]
        active_para_head = [b for b in active_blocks if b.get("block_type") in ("paragraph", "heading")]
        active_tables = [b for b in active_blocks if b.get("block_type") == "table"]
        active_pictures = [b for b in active_blocks if b.get("block_type") == "picture"]
        active_page_breaks = [b for b in active_blocks if b.get("block_type") == "page_break"]

        active_notes = [n for n in notes if isinstance(n, dict) and n.get("document_id") == doc_id and n.get("status") == "active"]
        active_spans = [s for s in spans if isinstance(s, dict) and s.get("document_id") == doc_id and s.get("status") == "active"]
        active_styles = [st for st in styles if isinstance(st, dict) and st.get("document_id") == doc_id and st.get("status") == "active"]
        active_table_formats = [tf for tf in table_formats if isinstance(tf, dict) and tf.get("document_id") == doc_id and tf.get("status") == "active"]

        out = {
            "document": {
                "id": doc.get("id"),
                "directory": doc.get("directory"),
                "filename": doc.get("filename"),
                "full_path": doc.get("full_path"),
                "title": doc.get("title"),
                "author": doc.get("author"),
                "status": doc.get("status"),
                "content_version": doc.get("content_version"),
                "file_sha256": doc.get("file_sha256"),
                "file_size_bytes": doc.get("file_size_bytes"),
                "protected": True if doc.get("status") == "protected" else False,
                "protection_algorithm": doc.get("protection_algorithm"),
                "created_at": doc.get("created_at"),
                "updated_at": doc.get("updated_at"),
                "last_indexed_at": doc.get("last_indexed_at"),
            },
            "counts": {
                "blocks_total": len(active_blocks),
                "paragraphs_and_headings": len(active_para_head),
                "tables": len(active_tables),
                "pictures": len(active_pictures),
                "page_breaks": len(active_page_breaks),
                "notes": len(active_notes),
                "text_spans": len(active_spans),
                "styles": len(active_styles),
                "table_formats": len(active_table_formats),
            }
        }
        _log("ok", None, {"filename": full_path, "document_id": doc_id})
        return out
    except Exception as e:
        _log("error", "CONFLICT", {"exception": str(e)})
        return _err("CONFLICT", "internal error")

def get_document_text(filename, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "get_document_text"

    def _log(status, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        if "\x00" in s or re.match(r"^[a-zA-Z]+://", s):
            return None
        s = re.sub(r"/+", "/", s)
        if s.startswith("./"):
            s = s[2:]
        if not s.lower().endswith(".docx"):
            s += ".docx"
        return s

    def _cands(norm_full):
        if not norm_full:
            return []
        xs = [norm_full]
        if norm_full.startswith("/"):
            xs.append(norm_full.lstrip("/"))
        else:
            xs.append("/" + norm_full)
        out, seen = [], set()
        for x in xs:
            if x not in seen:
                seen.add(x); out.append(x)
        return out

    def _find_doc(docs, norm_full):
        for c in _cands(norm_full):
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    try:
        full_path = _norm_docx_full_path(filename)
        if full_path is None:
            _log("error", "VALIDATION_ERROR", {"field": "filename"})
            return _err("VALIDATION_ERROR", "filename must be a non-empty string (.docx will be appended if missing)")

        docs = _load("documents.json")
        blocks = _load("document_blocks.json")
        if not isinstance(docs, list): docs = []
        if not isinstance(blocks, list): blocks = []

        doc = _find_doc(docs, full_path)
        if not doc or doc.get("status") == "deleted":
            _log("error", "NOT_FOUND", {"filename": full_path})
            return _err("NOT_FOUND", "document not found", filename=full_path)

        if doc.get("status") == "protected":
            _log("error", "CONFLICT", {"filename": full_path})
            return _err("CONFLICT", "document is protected and disallows text extraction", filename=full_path)

        doc_id = doc.get("id")
        active = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc_id and b.get("status") == "active"]
        active.sort(key=lambda x: (x.get("ordinal") if isinstance(x.get("ordinal"), int) else 10**9, x.get("id") or ""))

        parts = []
        for b in active:
            bt = b.get("block_type")
            if bt in ("paragraph", "heading"):
                txt = b.get("text")
                if isinstance(txt, str) and txt != "":
                    parts.append(txt)
                else:
                    parts.append("")
            elif bt == "table":
                data = b.get("table_data")
                if isinstance(data, list):
                    for row in data:
                        if isinstance(row, list):
                            parts.extend([("" if c is None else str(c)) for c in row])
                # if no data, skip (structure-only)
        text = "\n".join([p for p in parts if p is not None])

        _log("ok", None, {"filename": full_path, "document_id": doc_id, "chars": len(text)})
        return {
            "filename": doc.get("full_path"),
            "document_id": doc_id,
            "content_version": doc.get("content_version"),
            "text": text
        }
    except Exception as e:
        _log("error", "CONFLICT", {"exception": str(e)})
        return _err("CONFLICT", "internal error")

def get_document_outline(filename, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()
    status_code = "OK"

    def _norm_full_path(p):
        if not isinstance(p, str):
            return None
        p = p.strip()
        if not p:
            return None
        if not p.lower().endswith(".docx"):
            p = p + ".docx"
        p = p.replace("\\", "/")
        while "//" in p:
            p = p.replace("//", "/")
        return p

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _dt_out(dt):
        if dt is None:
            return None
        if isinstance(dt, datetime.datetime):
            return dt.replace(microsecond=0).isoformat() + "Z"
        return dt

    def _record(endpoint, cred, status, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        latency_ms = int((now - start).total_seconds() * 1000)
        row = {
            "id": f"req_{now.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": cred,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now.replace(microsecond=0).isoformat() + "Z",
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    full_path = _norm_full_path(filename)
    if full_path is None:
        status_code = "VALIDATION_ERROR"
        _record("get_document_outline", None, status_code, {"reason": "invalid_filename"})
        return _err("VALIDATION_ERROR", "filename is required and must be a non-empty string")

    docs = _load("documents.json")
    doc = None
    for d in docs:
        if isinstance(d, dict) and d.get("full_path") == full_path:
            doc = d
            break
    if not doc:
        status_code = "NOT_FOUND"
        _record("get_document_outline", None, status_code)
        return _err("NOT_FOUND", "document not found")

    if doc.get("status") == "deleted":
        status_code = "NOT_FOUND"
        _record("get_document_outline", None, status_code)
        return _err("NOT_FOUND", "document not found")

    # Cached outline usage: only if last_indexed_at is "recent enough" (<= 5 minutes old)
    now = datetime.datetime.utcnow()
    last_idx = _parse_dt(doc.get("last_indexed_at"))
    cache_fresh = False
    if last_idx is not None:
        age = (now - last_idx).total_seconds()
        cache_fresh = age >= 0 and age <= 300

    outline = None
    if cache_fresh and isinstance(doc.get("cached_outline"), (dict, list)):
        outline = doc.get("cached_outline")
    else:
        blocks = _load("document_blocks.json")
        active = [
            b for b in blocks
            if isinstance(b, dict)
            and b.get("document_id") == doc.get("id")
            and b.get("status") == "active"
        ]
        active.sort(key=lambda b: (b.get("ordinal") if isinstance(b.get("ordinal"), int) else 10**18, b.get("id") or ""))

        # Build headings tree from active heading blocks
        heading_blocks = [
            b for b in active
            if b.get("block_type") == "heading"
            and isinstance(b.get("heading_level"), int)
            and 1 <= b.get("heading_level") <= 9
        ]

        root = {"type": "root", "children": []}
        stack = [(0, root)]  # (level, node)

        for hb in heading_blocks:
            lvl = hb.get("heading_level")
            node = {
                "type": "heading",
                "block_id": hb.get("id"),
                "ordinal": hb.get("ordinal"),
                "level": lvl,
                "text": hb.get("text"),
                "children": []
            }
            while stack and stack[-1][0] >= lvl:
                stack.pop()
            parent = stack[-1][1] if stack else root
            parent["children"].append(node)
            stack.append((lvl, node))

        # Also include a lightweight ordered block list for "structure and block order"
        block_order = []
        for b in active:
            block_order.append({
                "block_id": b.get("id"),
                "ordinal": b.get("ordinal"),
                "block_type": b.get("block_type"),
                "heading_level": b.get("heading_level"),
                "text_preview": (b.get("text")[:200] if isinstance(b.get("text"), str) else None),
            })

        outline = {
            "document": {
                "id": doc.get("id"),
                "full_path": doc.get("full_path"),
                "directory": doc.get("directory"),
                "filename": doc.get("filename"),
                "title": doc.get("title"),
                "author": doc.get("author"),
                "status": doc.get("status"),
                "content_version": doc.get("content_version"),
                "updated_at": doc.get("updated_at"),
            },
            "headings_tree": root["children"],
            "block_order": block_order,
            "generated_at": _dt_out(now),
        }

        # Persist cache + last_indexed_at
        doc["cached_outline"] = outline
        doc["last_indexed_at"] = now.replace(microsecond=0).isoformat() + "Z"
        doc["updated_at"] = doc.get("updated_at")  # do not treat indexing as a content mutation
        _save("documents.json", docs)

    _record("get_document_outline", None, status_code)
    return {"outline": outline}

def list_available_documents(directory=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "list_available_documents"

    def _log(status, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    try:
        if directory is None:
            directory = "."
        if not isinstance(directory, str):
            _log("error", "VALIDATION_ERROR", {"field": "directory"})
            return _err("VALIDATION_ERROR", "directory must be a string")
        directory = directory.strip()
        if not directory:
            _log("error", "VALIDATION_ERROR", {"field": "directory"})
            return _err("VALIDATION_ERROR", "directory must be a non-empty string")

        directory = directory.replace("\\", "/")
        directory = re.sub(r"/+", "/", directory)
        if directory.endswith("/") and directory != "/":
            directory = directory[:-1]

        docs = _load("documents.json")
        if not isinstance(docs, list): docs = []

        allowed = {"active", "protected", "archived"}
        filenames = []
        for d in docs:
            if not isinstance(d, dict):
                continue
            if d.get("directory") != directory:
                continue
            if d.get("status") not in allowed:
                continue
            fn = d.get("filename")
            if isinstance(fn, str) and fn.lower().endswith(".docx"):
                filenames.append(fn)

        filenames = sorted(set(filenames), key=lambda s: s.lower())

        # Per audit: a directory with no documents should not be an error in this datastore-backed API.
        _log("ok", None, {"directory": directory, "count": len(filenames)})
        return {"directory": directory, "filenames": filenames, "count": len(filenames)}
    except Exception as e:
        _log("error", "CONFLICT", {"exception": str(e)})
        return _err("CONFLICT", "internal error")

def add_heading(filename, text, level=1, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()
    status_code = "OK"

    def _record(endpoint, cred, status, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        latency_ms = int((now - start).total_seconds() * 1000)
        row = {
            "id": f"req_{now.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": cred,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now.replace(microsecond=0).isoformat() + "Z",
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _norm_full_path(p):
        if not isinstance(p, str):
            return None
        p = p.strip()
        if not p:
            return None
        if not p.lower().endswith(".docx"):
            p = p + ".docx"
        p = p.replace("\\", "/")
        while "//" in p:
            p = p.replace("//", "/")
        return p

    def _new_id(prefix, existing_ids):
        now = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        base = f"{prefix}_{now}"
        if base not in existing_ids:
            return base
        i = 2
        while f"{base}_{i}" in existing_ids:
            i += 1
        return f"{base}_{i}"

    full_path = _norm_full_path(filename)
    if full_path is None:
        status_code = "VALIDATION_ERROR"
        _record("add_heading", None, status_code, {"reason": "invalid_filename"})
        return _err("VALIDATION_ERROR", "filename is required and must be a non-empty string")

    if not isinstance(text, str) or not text.strip():
        status_code = "VALIDATION_ERROR"
        _record("add_heading", None, status_code, {"reason": "invalid_text"})
        return _err("VALIDATION_ERROR", "text is required and must be a non-empty string")

    if not isinstance(level, int) or not (1 <= level <= 9):
        status_code = "VALIDATION_ERROR"
        _record("add_heading", None, status_code, {"reason": "invalid_level"})
        return _err("VALIDATION_ERROR", "level must be an integer between 1 and 9")

    docs = _load("documents.json")
    doc = None
    for d in docs:
        if isinstance(d, dict) and d.get("full_path") == full_path:
            doc = d
            break
    if not doc or doc.get("status") == "deleted":
        status_code = "NOT_FOUND"
        _record("add_heading", None, status_code)
        return _err("NOT_FOUND", "document not found")

    if doc.get("status") == "protected":
        status_code = "CONFLICT"
        _record("add_heading", None, status_code, {"reason": "document_protected"})
        return _err("CONFLICT", "document is protected")

    if doc.get("status") not in ("active", "archived"):
        status_code = "INVALID_TRANSITION"
        _record("add_heading", None, status_code, {"reason": "invalid_document_status"})
        return _err("INVALID_TRANSITION", "cannot modify document in its current status")

    blocks = _load("document_blocks.json")
    if not isinstance(blocks, list):
        blocks = []

    active_blocks = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc.get("id") and b.get("status") == "active"]
    max_ord = -1
    for b in active_blocks:
        o = b.get("ordinal")
        if isinstance(o, int) and o > max_ord:
            max_ord = o
    new_ordinal = max_ord + 1

    # Enforce constraints
    if any(isinstance(b, dict) and b.get("document_id") == doc.get("id") and b.get("status") == "active" and b.get("ordinal") == new_ordinal for b in blocks):
        status_code = "CONFLICT"
        _record("add_heading", None, status_code, {"reason": "ordinal_conflict"})
        return _err("CONFLICT", "could not allocate new block ordinal")

    existing_ids = {b.get("id") for b in blocks if isinstance(b, dict) and isinstance(b.get("id"), str)}
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    new_block = {
        "id": _new_id("blk", existing_ids),
        "document_id": doc.get("id"),
        "block_type": "heading",
        "ordinal": new_ordinal,
        "status": "active",
        "text": text,
        "paragraph_style": None,
        "heading_level": level,
        "table_rows": None,
        "table_cols": None,
        "table_data": None,
        "image_path": None,
        "image_width_in": None,
        "created_at": now,
        "updated_at": now,
    }

    blocks.append(new_block)
    _save("document_blocks.json", blocks)

    # Increment content_version and update timestamps; clear stale caches
    cv = doc.get("content_version")
    if not isinstance(cv, int) or cv < 1:
        cv = 1
    doc["content_version"] = cv + 1
    doc["updated_at"] = now
    doc["last_indexed_at"] = None
    doc["cached_full_text"] = None
    doc["cached_outline"] = None
    _save("documents.json", docs)

    # Return updated outline (same as get_document_outline derivation)
    active_blocks = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc.get("id") and b.get("status") == "active"]
    active_blocks.sort(key=lambda b: (b.get("ordinal") if isinstance(b.get("ordinal"), int) else 10**18, b.get("id") or ""))
    heading_blocks = [
        b for b in active_blocks
        if b.get("block_type") == "heading"
        and isinstance(b.get("heading_level"), int)
        and 1 <= b.get("heading_level") <= 9
    ]
    root = {"type": "root", "children": []}
    stack = [(0, root)]
    for hb in heading_blocks:
        lvl = hb.get("heading_level")
        node = {
            "type": "heading",
            "block_id": hb.get("id"),
            "ordinal": hb.get("ordinal"),
            "level": lvl,
            "text": hb.get("text"),
            "children": []
        }
        while stack and stack[-1][0] >= lvl:
            stack.pop()
        parent = stack[-1][1] if stack else root
        parent["children"].append(node)
        stack.append((lvl, node))

    block_order = [{
        "block_id": b.get("id"),
        "ordinal": b.get("ordinal"),
        "block_type": b.get("block_type"),
        "heading_level": b.get("heading_level"),
        "text_preview": (b.get("text")[:200] if isinstance(b.get("text"), str) else None),
    } for b in active_blocks]

    outline = {
        "document": {
            "id": doc.get("id"),
            "full_path": doc.get("full_path"),
            "directory": doc.get("directory"),
            "filename": doc.get("filename"),
            "title": doc.get("title"),
            "author": doc.get("author"),
            "status": doc.get("status"),
            "content_version": doc.get("content_version"),
            "updated_at": doc.get("updated_at"),
        },
        "headings_tree": root["children"],
        "block_order": block_order,
        "generated_at": now,
    }

    _record("add_heading", None, status_code, {"document_id": doc.get("id"), "new_block_id": new_block["id"]})
    return {"outline": outline}

def add_picture(filename, image_path, width=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({
                "id": f"req_{secrets.token_hex(12)}",
                "endpoint": "add_picture",
                "timestamp": now,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        s = re.sub(r"/+", "/", s)
        if not s.lower().endswith(".docx"):
            s = s + ".docx"
        if s.startswith("./"):
            s = s[2:]
        return s

    def _find_doc_by_any_path(docs, norm_full):
        candidates = [norm_full]
        if norm_full.startswith("/"):
            candidates.append(norm_full.lstrip("/"))
        else:
            candidates.append("/" + norm_full)
        for c in candidates:
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    if not isinstance(filename, str) or not filename.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filename must be a non-empty string")
    if not isinstance(image_path, str) or not image_path.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "image_path must be a non-empty string")
    if width is not None:
        if not isinstance(width, (int, float)):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "width must be a number or null")
        if width <= 0:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "width must be > 0 when provided")

    docs = _load("documents.json")
    blocks = _load("document_blocks.json")
    if not isinstance(docs, list): docs = []
    if not isinstance(blocks, list): blocks = []

    full_path = _norm_docx_full_path(filename)
    doc = _find_doc_by_any_path(docs, full_path)
    if not doc or doc.get("status") == "deleted":
        _log("error", "NOT_FOUND", {"filename": full_path})
        return _err("NOT_FOUND", "document not found", filename=full_path)

    # For this datastore, image_path is treated as a server path. Require it to exist on disk OR be referenced in any existing picture block.
    img = image_path.strip().replace("\\", "/")
    img_exists = os.path.exists(img)
    if not img_exists:
        referenced = any(isinstance(b, dict) and b.get("block_type") == "picture" and b.get("image_path") == img for b in blocks)
        if not referenced:
            _log("error", "NOT_FOUND", {"image_path": img})
            return _err("NOT_FOUND", "image_path not found", image_path=img)

    # Append new picture block at end (max ordinal + 1 among active blocks)
    doc_id = doc.get("id")
    active = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc_id and b.get("status") == "active"]
    max_ord = max([b.get("ordinal", -1) for b in active], default=-1)
    new_block = {
        "id": f"owd_blk_{secrets.token_hex(14)}",
        "document_id": doc_id,
        "block_type": "picture",
        "ordinal": (max_ord + 1),
        "status": "active",
        "text": None,
        "paragraph_style": None,
        "heading_level": None,
        "table_rows": None,
        "table_cols": None,
        "table_data": None,
        "image_path": img,
        "image_width_in": float(width) if width is not None else None,
        "created_at": now,
        "updated_at": now,
    }
    blocks.append(new_block)

    # Mutating tool rules: increment document.content_version, updated_at; require status != deleted already checked.
    try:
        cv = int(doc.get("content_version") or 0)
    except Exception:
        cv = 0
    doc["content_version"] = max(1, cv) + 1
    doc["updated_at"] = now
    doc["cached_full_text"] = None
    doc["cached_outline"] = None
    doc["last_indexed_at"] = None

    _save("document_blocks.json", blocks)
    _save("documents.json", docs)

    # Return updated outline (derived)
    def _build_outline(doc_id_):
        act = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc_id_ and b.get("status") == "active"]
        act.sort(key=lambda x: (x.get("ordinal", 0), x.get("created_at", "")))
        headings = [b for b in act if b.get("block_type") == "heading" and isinstance(b.get("heading_level"), int)]
        outline = []
        stack = []
        for h in headings:
            node = {"block_id": h.get("id"), "title": h.get("text") or "", "level": h.get("heading_level"), "ordinal": h.get("ordinal"), "children": []}
            lvl = node["level"]
            while stack and stack[-1]["level"] >= lvl:
                stack.pop()
            if stack:
                stack[-1]["children"].append(node)
            else:
                outline.append(node)
            stack.append(node)
        return outline

    out = {"document": doc, "added_block": new_block, "outline": _build_outline(doc_id)}
    _log("success")
    return out

def add_table(filename, rows, cols, data=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_doc_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        p = p.strip()
        if not p.lower().endswith(".docx"):
            p = p + ".docx"
        p = p.replace("\\", "/")
        while "//" in p:
            p = p.replace("//", "/")
        return p

    def _new_id(prefix):
        import secrets
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{secrets.token_hex(6)}"

    def _build_outline(doc_id, blocks):
        active = [b for b in blocks if b.get("document_id") == doc_id and b.get("status") == "active"]
        active.sort(key=lambda x: (x.get("ordinal", 0), x.get("created_at", "")))
        headings = [b for b in active if b.get("block_type") == "heading" and isinstance(b.get("heading_level"), int)]
        outline = []
        stack = []
        for h in headings:
            node = {
                "block_id": h.get("id"),
                "title": h.get("text") or "",
                "level": h.get("heading_level"),
                "ordinal": h.get("ordinal"),
                "children": []
            }
            lvl = node["level"]
            while stack and stack[-1]["level"] >= lvl:
                stack.pop()
            if stack:
                stack[-1]["children"].append(node)
            else:
                outline.append(node)
            stack.append(node)
        return outline

    start = datetime.datetime.utcnow()
    requests = _load("request_logs.json")

    def _log(status, code=None):
        end = datetime.datetime.utcnow()
        latency_ms = int((end - start).total_seconds() * 1000)
        requests.append({
            "id": _new_id("req"),
            "endpoint": "add_table",
            "status": status,
            "error_code": code,
            "latency_ms": latency_ms,
            "timestamp": _now()
        })
        _save("request_logs.json", requests)

    # Validation
    full_path = _norm_doc_path(filename)
    if full_path is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filename must be a non-empty string")
    if not isinstance(rows, int) or isinstance(rows, bool) or rows < 1:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "rows must be a positive integer")
    if not isinstance(cols, int) or isinstance(cols, bool) or cols < 1:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cols must be a positive integer")

    if data is not None:
        if not isinstance(data, list):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "data must be a 2D array of strings when provided")
        if len(data) != rows:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "data must match rows x cols", expected_rows=rows, expected_cols=cols)
        for r in data:
            if not isinstance(r, list) or len(r) != cols:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "data must match rows x cols", expected_rows=rows, expected_cols=cols)
            for c in r:
                if not isinstance(c, str):
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "data cells must be strings")

    docs = _load("documents.json")
    blocks = _load("document_blocks.json")

    doc = next((d for d in docs if d.get("full_path") == full_path), None)
    if not doc:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "document not found", filename=full_path)

    if doc.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "document is deleted", filename=full_path)

    # Enforce protected edit lock (tool says FORBIDDEN; using UNAUTHORIZED per allowed codes)
    if doc.get("status") == "protected":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "document is protected/locked for editing", filename=full_path)

    # Append at end
    active_doc_blocks = [b for b in blocks if b.get("document_id") == doc.get("id") and b.get("status") == "active"]
    max_ord = -1
    for b in active_doc_blocks:
        o = b.get("ordinal")
        if isinstance(o, int) and o > max_ord:
            max_ord = o
    next_ord = max_ord + 1

    now = _now()
    new_block = {
        "id": _new_id("blk"),
        "document_id": doc.get("id"),
        "block_type": "table",
        "ordinal": next_ord,
        "status": "active",
        "text": None,
        "paragraph_style": None,
        "heading_level": None,
        "table_rows": rows,
        "table_cols": cols,
        "table_data": data if data is not None else None,
        "image_path": None,
        "image_width_in": None,
        "created_at": now,
        "updated_at": now
    }

    blocks.append(new_block)
    _save("document_blocks.json", blocks)

    cv = doc.get("content_version")
    if not isinstance(cv, int) or cv < 1:
        cv = 1
    doc["content_version"] = cv + 1
    doc["updated_at"] = now
    doc["last_indexed_at"] = None
    doc["cached_full_text"] = None
    doc["cached_outline"] = None
    _save("documents.json", docs)

    outline = _build_outline(doc.get("id"), blocks)
    _log("ok")
    return {
        "document": {
            "id": doc.get("id"),
            "full_path": doc.get("full_path"),
            "directory": doc.get("directory"),
            "filename": doc.get("filename"),
            "status": doc.get("status"),
            "content_version": doc.get("content_version"),
            "updated_at": doc.get("updated_at")
        },
        "added_block": new_block,
        "outline": outline
    }

