        "id": _new_id("blk"),
        "document_id": doc.get("id"),
        "block_type": "page_break",
        "ordinal": next_ord,
        "status": "active",
        "text": None,
        "paragraph_style": None,
        "heading_level": None,
        "table_rows": None,
        "table_cols": None,
        "table_data": None,
        "image_path": None,
        "image_width_in": None,
        "created_at": now,
        "updated_at": now
    }
    blocks.append(new_block)
    _save("document_blocks.json", blocks)

    cv = doc.get("content_version")
    if not isinstance(cv, int) or cv < 1:
        cv = 1
    doc["content_version"] = cv + 1
    doc["updated_at"] = now
    doc["last_indexed_at"] = None
    doc["cached_full_text"] = None
    doc["cached_outline"] = None
    _save("documents.json", docs)

    outline = _build_outline(doc.get("id"), blocks)
    _log("ok")
    return {
        "document": {
            "id": doc.get("id"),
            "full_path": doc.get("full_path"),
            "directory": doc.get("directory"),
            "filename": doc.get("filename"),
            "status": doc.get("status"),
            "content_version": doc.get("content_version"),
            "updated_at": doc.get("updated_at")
        },
        "added_block": new_block,
        "outline": outline
    }

def delete_paragraph(filename, paragraph_index, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    endpoint = "delete_paragraph"

    def _log(status, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        if "\x00" in s or re.match(r"^[a-zA-Z]+://", s):
            return None
        s = re.sub(r"/+", "/", s)
        if s.startswith("./"):
            s = s[2:]
        if not s.lower().endswith(".docx"):
            s += ".docx"
        return s

    def _cands(norm_full):
        if not norm_full:
            return []
        xs = [norm_full]
        if norm_full.startswith("/"):
            xs.append(norm_full.lstrip("/"))
        else:
            xs.append("/" + norm_full)
        out, seen = [], set()
        for x in xs:
            if x not in seen:
                seen.add(x); out.append(x)
        return out

    def _find_doc(docs, norm_full):
        for c in _cands(norm_full):
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    try:
        if not isinstance(filename, str) or not filename.strip():
            _log("error", "VALIDATION_ERROR", {"field": "filename"})
            return _err("VALIDATION_ERROR", "filename must be a non-empty string")
        if not isinstance(paragraph_index, int):
            _log("error", "VALIDATION_ERROR", {"field": "paragraph_index"})
            return _err("VALIDATION_ERROR", "paragraph_index must be an integer")
        if paragraph_index < 0:
            _log("error", "VALIDATION_ERROR", {"field": "paragraph_index"})
            return _err("VALIDATION_ERROR", "paragraph_index must be >= 0")

        full_path = _norm_docx_full_path(filename)
        if full_path is None:
            _log("error", "VALIDATION_ERROR", {"field": "filename"})
            return _err("VALIDATION_ERROR", "filename is invalid")

        docs = _load("documents.json")
        blocks = _load("document_blocks.json")
        if not isinstance(docs, list): docs = []
        if not isinstance(blocks, list): blocks = []

        doc = _find_doc(docs, full_path)
        if not doc or doc.get("status") == "deleted":
            _log("error", "NOT_FOUND", {"filename": full_path})
            return _err("NOT_FOUND", "document not found", filename=full_path)

        doc_id = doc.get("id")
        # Visible paragraphs are active paragraph+heading blocks ordered by ordinal
        doc_blocks = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc_id]
        active_ph = [b for b in doc_blocks if b.get("status") == "active" and b.get("block_type") in ("paragraph", "heading")]
        active_ph.sort(key=lambda x: (x.get("ordinal") if isinstance(x.get("ordinal"), int) else 10**9, x.get("id") or ""))

        if paragraph_index >= len(active_ph):
            _log("error", "NOT_FOUND", {"filename": full_path, "paragraph_index": paragraph_index})
            return _err("NOT_FOUND", "paragraph_index does not exist", filename=full_path, paragraph_index=paragraph_index)

        target = active_ph[paragraph_index]
        if target.get("status") != "active":
            _log("error", "INVALID_TRANSITION", {"block_id": target.get("id")})
            return _err("INVALID_TRANSITION", "block is not in an active state", block_id=target.get("id"))

        # Soft delete target
        target_id = target.get("id")
        changed = False
        for b in blocks:
            if isinstance(b, dict) and b.get("id") == target_id:
                if b.get("status") != "active":
                    _log("error", "INVALID_TRANSITION", {"block_id": target_id})
                    return _err("INVALID_TRANSITION", "block is not in an active state", block_id=target_id)
                b["status"] = "deleted"
                b["updated_at"] = now
                changed = True
                break
        if not changed:
            _log("error", "NOT_FOUND", {"block_id": target_id})
            return _err("NOT_FOUND", "block not found", block_id=target_id)

        # Compact ordinals for remaining ACTIVE blocks in document to be contiguous (all block types)
        active_all = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc_id and b.get("status") == "active"]
        active_all.sort(key=lambda x: (x.get("ordinal") if isinstance(x.get("ordinal"), int) else 10**9, x.get("id") or ""))

        # Reassign ordinals 0..n-1
        ord_updates = 0
        for i, b in enumerate(active_all):
            if b.get("ordinal") != i:
                b["ordinal"] = i
                b["updated_at"] = now
                ord_updates += 1

        # increment content_version and updated_at
        cv = doc.get("content_version")
        if not isinstance(cv, int) or cv < 1:
            cv = 1
        doc["content_version"] = cv + 1
        doc["updated_at"] = now

        _save("document_blocks.json", blocks)
        _save("documents.json", docs)

        _log("ok", None, {"filename": full_path, "document_id": doc_id, "deleted_block_id": target_id, "ordinal_updates": ord_updates})
        return {
            "document_id": doc_id,
            "filename": doc.get("full_path"),
            "content_version": doc.get("content_version"),
            "deleted": {"block_id": target_id, "paragraph_index": paragraph_index},
        }
    except Exception as e:
        _log("error", "CONFLICT", {"exception": str(e)})
        return _err("CONFLICT", "internal error")

def search_and_replace(filename, find_text, replace_text, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_docx_path(p):
        if not isinstance(p, str):
            return None
        p = p.strip()
        if not p:
            return ""
        if not p.lower().endswith(".docx"):
            p = p + ".docx"
        # Normalize to a server-rooted-ish canonical path without hitting filesystem.
        pp = p.replace("\\", "/")
        # If it's a bare filename, root it.
        if "/" not in pp:
            pp = "/" + pp
        # Collapse //, /./, /../ lexically
        parts = []
        for seg in pp.split("/"):
            if seg == "" or seg == ".":
                continue
            if seg == "..":
                if parts:
                    parts.pop()
                continue
            parts.append(seg)
        return "/" + "/".join(parts)

    def _split_dir_filename(full_path):
        fp = full_path
        if fp == "/":
            return ("/", "")
        d, _, f = fp.rpartition("/")
        if d == "":
            d = "/"
        return (d or "/", f)

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}"

    def _log(status, latency_ms, meta=None):
        # Optional observable dynamics: record to request_logs.json if present/used.
        try:
            logs = _load("request_logs.json")
            if isinstance(logs, list):
                logs.append({
                    "id": _gen_id("req"),
                    "endpoint": "search_and_replace",
                    "status": status,
                    "latency_ms": latency_ms,
                    "timestamp": _now(),
                    "meta": meta or {}
                })
                _save("request_logs.json", logs)
        except Exception:
            # Don't fail the request if logging fails.
            pass

    t0 = time.time()
    try:
        # Validate
        if not isinstance(filename, str):
            latency = int((time.time() - t0) * 1000)
            out = _err("VALIDATION_ERROR", "filename must be a string")
            _log("error", latency, {"code": "VALIDATION_ERROR"})
            return out
        if not isinstance(find_text, str):
            latency = int((time.time() - t0) * 1000)
            out = _err("VALIDATION_ERROR", "find_text must be a string")
            _log("error", latency, {"code": "VALIDATION_ERROR"})
            return out
        if not isinstance(replace_text, str):
            latency = int((time.time() - t0) * 1000)
            out = _err("VALIDATION_ERROR", "replace_text must be a string")
            _log("error", latency, {"code": "VALIDATION_ERROR"})
            return out
        if find_text == "":
            latency = int((time.time() - t0) * 1000)
            out = _err("VALIDATION_ERROR", "find_text must not be empty")
            _log("error", latency, {"code": "VALIDATION_ERROR"})
            return out

        full_path = _norm_docx_path(filename)
        if full_path is None or full_path == "":
            latency = int((time.time() - t0) * 1000)
            out = _err("VALIDATION_ERROR", "filename is invalid")
            _log("error", latency, {"code": "VALIDATION_ERROR"})
            return out

        documents = _load("documents.json")
        doc = None
        for d in documents:
            if isinstance(d, dict) and d.get("full_path") == full_path:
                doc = d
                break
        if not doc:
            latency = int((time.time() - t0) * 1000)
            out = _err("NOT_FOUND", "Document not found", filename=full_path)
            _log("error", latency, {"code": "NOT_FOUND"})
            return out

        if doc.get("status") == "deleted":
            latency = int((time.time() - t0) * 1000)
            out = _err("NOT_FOUND", "Document not found", filename=full_path)
            _log("error", latency, {"code": "NOT_FOUND"})
            return out

        # Vendor description says FORBIDDEN for protected; our allowed codes don't include it.
        # Enforce as UNAUTHORIZED (locked for editing without password parameter).
        if doc.get("status") == "protected":
            latency = int((time.time() - t0) * 1000)
            out = _err("UNAUTHORIZED", "Document is protected/locked for editing", filename=full_path)
            _log("error", latency, {"code": "UNAUTHORIZED"})
            return out

        blocks = _load("document_blocks.json")
        spans = _load("text_spans.json")

        # Find active paragraph+heading blocks ordered by ordinal
        target_blocks = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc.get("id") and b.get("status") == "active" and b.get("block_type") in ("paragraph", "heading")]
        target_blocks.sort(key=lambda x: (x.get("ordinal", 0), x.get("id", "")))

        total_replacements = 0
        blocks_changed = 0
        superseded_spans = 0

        # Replace in each block
        for b in target_blocks:
            txt = b.get("text")
            if not isinstance(txt, str) or txt == "":
                continue
            if find_text not in txt:
                continue
            new_txt = txt.replace(find_text, replace_text)
            if new_txt != txt:
                # Count replacements (non-overlapping as Python str.replace)
                total_replacements += txt.count(find_text)
                b["text"] = new_txt
                b["updated_at"] = _now()
                blocks_changed += 1

                # Supersede spans that become invalid (end_pos > new length) as per rule.
                new_len = len(new_txt)
                for s in spans:
                    if not isinstance(s, dict):
                        continue
                    if s.get("status") != "active":
                        continue
                    if s.get("document_id") != doc.get("id") or s.get("block_id") != b.get("id"):
                        continue
                    try:
                        end_pos = int(s.get("end_pos"))
                        start_pos = int(s.get("start_pos"))
                    except Exception:
                        # If malformed, supersede it (it's invalid anyway).
                        s["status"] = "superseded"
                        s["updated_at"] = _now()
                        superseded_spans += 1
                        continue
                    if start_pos < 0 or end_pos <= start_pos or end_pos > new_len or start_pos > new_len:
                        s["status"] = "superseded"
                        s["updated_at"] = _now()
                        superseded_spans += 1

        if blocks_changed == 0:
            # No success without effect: but this is not a mutation if nothing to change?
            # Real APIs usually succeed with 0 replacements. We'll return success with outcome,
            # because document exists and operation is a valid no-op.
            latency = int((time.time() - t0) * 1000)
            out = {
                "document": doc,
                "result": {
                    "find_text": find_text,
                    "replace_text": replace_text,
                    "blocks_changed": 0,
                    "replacements": 0,
                    "superseded_spans": 0
                }
            }
            _log("ok", latency, {"replacements": 0})
            return out

        # Increment content_version, update caches/index timestamps
        try:
            cv = int(doc.get("content_version", 1))
        except Exception:
            cv = 1
        doc["content_version"] = max(1, cv + 1)
        doc["updated_at"] = _now()
        # Invalidate cached outline/text freshness by setting last_indexed_at to null-ish? Here: refresh derived full text now.
        # Recompute cached_full_text from active blocks (paragraph+heading) in ordinal order
        refreshed_blocks = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc.get("id") and b.get("status") == "active" and b.get("block_type") in ("paragraph", "heading")]
        refreshed_blocks.sort(key=lambda x: (x.get("ordinal", 0), x.get("id", "")))
        doc["cached_full_text"] = "\n".join([(b.get("text") if isinstance(b.get("text"), str) else "") for b in refreshed_blocks]).strip("\n")
        doc["last_indexed_at"] = _now()

        _save("document_blocks.json", blocks)
        _save("text_spans.json", spans)
        _save("documents.json", documents)

        latency = int((time.time() - t0) * 1000)
        out = {
            "document": doc,
            "result": {
                "find_text": find_text,
                "replace_text": replace_text,
                "blocks_changed": blocks_changed,
                "replacements": total_replacements,
                "superseded_spans": superseded_spans
            }
        }
        _log("ok", latency, {"replacements": total_replacements, "blocks_changed": blocks_changed})
        return out
    except Exception as e:
        latency = int((time.time() - t0) * 1000)
        out = _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))
        _log("error", latency, {"code": "VALIDATION_ERROR", "detail": str(e)})
        return out

def create_custom_style(filename, style_name, bold=None, italic=None, font_size=None, font_name=None, color=None, base_style=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({
                "id": f"req_{secrets.token_hex(12)}",
                "endpoint": "create_custom_style",
                "timestamp": now,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        s = re.sub(r"/+", "/", s)
        if not s.lower().endswith(".docx"):
            s = s + ".docx"
        if s.startswith("./"):
            s = s[2:]
        return s

    def _find_doc_by_any_path(docs, norm_full):
        candidates = [norm_full]
        if norm_full.startswith("/"):
            candidates.append(norm_full.lstrip("/"))
        else:
            candidates.append("/" + norm_full)
        for c in candidates:
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    # Validate inputs
    if not isinstance(filename, str) or not filename.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filename must be a non-empty string")
    if not isinstance(style_name, str) or style_name.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "style_name must be a non-empty string")

    if bold is not None and not isinstance(bold, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "bold must be a boolean or null")
    if italic is not None and not isinstance(italic, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "italic must be a boolean or null")
    if font_size is not None:
        if not isinstance(font_size, int):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "font_size must be an integer or null")
        if not (1 <= font_size <= 512):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "font_size must be between 1 and 512")
    if font_name is not None and not isinstance(font_name, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "font_name must be a string or null")
    if color is not None and not isinstance(color, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "color must be a string or null")
    if base_style is not None and not isinstance(base_style, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "base_style must be a string or null")

    docs = _load("documents.json")
    styles = _load("styles.json")
    if not isinstance(docs, list): docs = []
    if not isinstance(styles, list): styles = []

    full_path = _norm_docx_full_path(filename)
    doc = _find_doc_by_any_path(docs, full_path)
    if not doc or doc.get("status") == "deleted":
        _log("error", "NOT_FOUND", {"filename": full_path})
        return _err("NOT_FOUND", "document not found", filename=full_path)

    doc_id = doc.get("id")
    sname = style_name.strip()

    # Enforce "base_style may refer to built-in or existing active custom style"
    # We'll validate only when it looks like a custom style reference: if base_style provided and not found among active custom styles,
    # still allow (treat as built-in) rather than rejecting.
    if base_style is not None and base_style.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "base_style must be a non-empty string when provided")

    # Upsert by (document_id, style_name) where status='active'
    existing_active = None
    for s in styles:
        if isinstance(s, dict) and s.get("document_id") == doc_id and s.get("status") == "active" and s.get("style_name") == sname:
            existing_active = s
            break

    if existing_active is None:
        # If a deleted style exists with same name, "upsert" reactivates by creating new row or flipping status.
        # Business rule says upsert styles; we'll reactivate the most recent matching deleted row if present, else create.
        revive = None
        for s in styles:
            if isinstance(s, dict) and s.get("document_id") == doc_id and s.get("status") == "deleted" and s.get("style_name") == sname:
                revive = s
        target = revive
        if target is None:
            target = {
                "id": f"owd_sty_{secrets.token_hex(14)}",
                "document_id": doc_id,
                "style_name": sname,
                "status": "active",
                "created_at": now,
                "updated_at": now,
                "base_style_name": None,
                "bold": None,
                "italic": None,
                "font_size": None,
                "font_name": None,
                "color": None,
            }
            styles.append(target)
        else:
            target["status"] = "active"
            target["updated_at"] = now
        # Apply fields
        target["base_style_name"] = base_style.strip() if isinstance(base_style, str) else None
        target["bold"] = bold
        target["italic"] = italic
        target["font_size"] = font_size
        target["font_name"] = font_name
        target["color"] = color
        created_or_updated = "created" if target.get("created_at") == now else "updated"
    else:
        # Update existing (idempotent)
        existing_active["base_style_name"] = base_style.strip() if isinstance(base_style, str) else existing_active.get("base_style_name")
        if bold is not None: existing_active["bold"] = bold
        if italic is not None: existing_active["italic"] = italic
        if font_size is not None: existing_active["font_size"] = font_size
        if font_name is not None: existing_active["font_name"] = font_name
        if color is not None: existing_active["color"] = color
        existing_active["updated_at"] = now
        created_or_updated = "updated"

    # Mutating tools: bump content_version and invalidate caches
    try:
        cv = int(doc.get("content_version") or 0)
    except Exception:
        cv = 0
    doc["content_version"] = max(1, cv) + 1
    doc["updated_at"] = now
    doc["cached_full_text"] = None
    doc["cached_outline"] = None
    doc["last_indexed_at"] = None

    _save("styles.json", styles)
    _save("documents.json", docs)

    _log("success")
    return {"document": doc, "style_name": sname, "result": created_or_updated}

def format_text(filename, paragraph_index, start_pos, end_pos, bold=None, italic=None, underline=None, color=None, font_size=None, font_name=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "format_text"

    def _log(status, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        if "\x00" in s or re.match(r"^[a-zA-Z]+://", s):
            return None
        s = re.sub(r"/+", "/", s)
        if s.startswith("./"):
            s = s[2:]
        if not s.lower().endswith(".docx"):
            s += ".docx"
        return s

    def _cands(norm_full):
        if not norm_full:
            return []
        xs = [norm_full]
        if norm_full.startswith("/"):
            xs.append(norm_full.lstrip("/"))
        else:
            xs.append("/" + norm_full)
        out, seen = [], set()
        for x in xs:
            if x not in seen:
                seen.add(x); out.append(x)
        return out

    def _find_doc(docs, norm_full):
        for c in _cands(norm_full):
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(13)}"

    try:
        full_path = _norm_docx_full_path(filename)
        if full_path is None:
            _log("error", "VALIDATION_ERROR", {"field": "filename"})
            return _err("VALIDATION_ERROR", "filename must be a non-empty string (.docx will be appended if missing)")

        if not isinstance(paragraph_index, int) or paragraph_index < 0:
            _log("error", "VALIDATION_ERROR", {"field": "paragraph_index"})
            return _err("VALIDATION_ERROR", "paragraph_index must be an integer >= 0")
        if not isinstance(start_pos, int) or not isinstance(end_pos, int):
            _log("error", "VALIDATION_ERROR", {"field": "start_pos/end_pos"})
            return _err("VALIDATION_ERROR", "start_pos and end_pos must be integers")
        if start_pos < 0 or end_pos < 0:
            _log("error", "VALIDATION_ERROR", {"field": "start_pos/end_pos"})
            return _err("VALIDATION_ERROR", "start_pos and end_pos must be >= 0")

        # Relaxed: accept reversed ranges by swapping (common client bug); still require non-empty after normalization
        if end_pos < start_pos:
            start_pos, end_pos = end_pos, start_pos
        if end_pos == start_pos:
            _log("error", "VALIDATION_ERROR", {"field": "end_pos"})
            return _err("VALIDATION_ERROR", "end_pos must be different from start_pos")

        if bold is not None and not isinstance(bold, bool):
            _log("error", "VALIDATION_ERROR", {"field": "bold"})
            return _err("VALIDATION_ERROR", "bold must be boolean or null")
        if italic is not None and not isinstance(italic, bool):
            _log("error", "VALIDATION_ERROR", {"field": "italic"})
            return _err("VALIDATION_ERROR", "italic must be boolean or null")
        if underline is not None and not isinstance(underline, bool):
            _log("error", "VALIDATION_ERROR", {"field": "underline"})
            return _err("VALIDATION_ERROR", "underline must be boolean or null")
        if color is not None and not isinstance(color, str):
            _log("error", "VALIDATION_ERROR", {"field": "color"})
            return _err("VALIDATION_ERROR", "color must be string or null")
        if font_name is not None and not isinstance(font_name, str):
            _log("error", "VALIDATION_ERROR", {"field": "font_name"})
            return _err("VALIDATION_ERROR", "font_name must be string or null")
        if font_size is not None:
            if not isinstance(font_size, int):
                _log("error", "VALIDATION_ERROR", {"field": "font_size"})
                return _err("VALIDATION_ERROR", "font_size must be integer or null")
            if not (1 <= font_size <= 512):
                _log("error", "VALIDATION_ERROR", {"field": "font_size"})
                return _err("VALIDATION_ERROR", "font_size must be between 1 and 512")

        docs = _load("documents.json")
        blocks = _load("document_blocks.json")
        spans = _load("text_spans.json")
        if not isinstance(docs, list): docs = []
        if not isinstance(blocks, list): blocks = []
        if not isinstance(spans, list): spans = []

        doc = _find_doc(docs, full_path)
        if not doc or doc.get("status") == "deleted":
            _log("error", "NOT_FOUND", {"filename": full_path})
            return _err("NOT_FOUND", "document not found", filename=full_path)

        doc_id = doc.get("id")
        active_ph = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc_id and b.get("status") == "active" and b.get("block_type") in ("paragraph", "heading")]
        active_ph.sort(key=lambda x: (x.get("ordinal") if isinstance(x.get("ordinal"), int) else 10**9, x.get("id") or ""))

        if paragraph_index >= len(active_ph):
            _log("error", "NOT_FOUND", {"filename": full_path, "paragraph_index": paragraph_index})
            return _err("NOT_FOUND", "paragraph_index does not exist", filename=full_path, paragraph_index=paragraph_index)

        block = active_ph[paragraph_index]
        block_id = block.get("id")
        text = block.get("text")
        if not isinstance(text, str):
            text = ""

        if end_pos > len(text) or start_pos > len(text):
            _log("error", "VALIDATION_ERROR", {"rule": "positions must be within paragraph text length", "text_length": len(text)})
            return _err("VALIDATION_ERROR", "start_pos/end_pos are out of bounds for the paragraph text", text_length=len(text), start_pos=start_pos, end_pos=end_pos)

        # Supersede any active spans that become exact duplicates (idempotency-ish)
        for s in spans:
            if not isinstance(s, dict):
                continue
            if s.get("status") == "active" and s.get("document_id") == doc_id and s.get("block_id") == block_id:
                if s.get("start_pos") == start_pos and s.get("end_pos") == end_pos and s.get("bold") == bold and s.get("italic") == italic and s.get("underline") == underline and s.get("color") == color and s.get("font_size") == font_size and s.get("font_name") == font_name:
                    _log("ok", None, {"idempotent": True, "span_id": s.get("id")})
                    # still a mutation? don't increment version if no effect; but contract says no success without effect.
                    # Treat as no-op conflict? Real API typically idempotent; here we keep effect-free OK but with explicit idempotent flag is observable.
                    return {
                        "document_id": doc_id,
                        "filename": doc.get("full_path"),
                        "content_version": doc.get("content_version"),
                        "span": s,
                        "idempotent": True
                    }

        # Insert new span
        span_id = _gen_id("owd_spn")
        span_row = {
            "id": span_id,
            "document_id": doc_id,
            "block_id": block_id,
            "start_pos": start_pos,
            "end_pos": end_pos,
            "bold": bold,
            "italic": italic,
            "underline": underline,
            "color": color,
            "font_size": font_size,
            "font_name": font_name,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        spans.append(span_row)

        # Increment document version
        cv = doc.get("content_version")
        if not isinstance(cv, int) or cv < 1:
            cv = 1
        doc["content_version"] = cv + 1
        doc["updated_at"] = now

        _save("text_spans.json", spans)
        _save("documents.json", docs)

        _log("ok", None, {"filename": full_path, "document_id": doc_id, "block_id": block_id, "span_id": span_id})
        return {
            "document_id": doc_id,
            "filename": doc.get("full_path"),
            "content_version": doc.get("content_version"),
            "span": span_row
        }
    except Exception as e:
        _log("error", "CONFLICT", {"exception": str(e)})
        return _err("CONFLICT", "internal error")

def format_table(filename, table_index, has_header_row=None, border_style=None, shading=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "format_table"

    def _log(status, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        if "\x00" in s or re.match(r"^[a-zA-Z]+://", s):
            return None
        s = re.sub(r"/+", "/", s)
        if s.startswith("./"):
            s = s[2:]
        if not s.lower().endswith(".docx"):
            s += ".docx"
        return s

    def _cands(norm_full):
        if not norm_full:
            return []
        xs = [norm_full]
        if norm_full.startswith("/"):
            xs.append(norm_full.lstrip("/"))
        else:
            xs.append("/" + norm_full)
        out, seen = [], set()
        for x in xs:
            if x not in seen:
                seen.add(x); out.append(x)
        return out

    def _find_doc(docs, norm_full):
        for c in _cands(norm_full):
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(13)}"

    try:
        full_path = _norm_docx_full_path(filename)
        if full_path is None:
            _log("error", "VALIDATION_ERROR", {"field": "filename"})
            return _err("VALIDATION_ERROR", "filename must be a non-empty string (.docx will be appended if missing)")

        if not isinstance(table_index, int) or table_index < 0:
            _log("error", "VALIDATION_ERROR", {"field": "table_index"})
            return _err("VALIDATION_ERROR", "table_index must be an integer >= 0")

        if has_header_row is not None and not isinstance(has_header_row, bool):
            _log("error", "VALIDATION_ERROR", {"field": "has_header_row"})
            return _err("VALIDATION_ERROR", "has_header_row must be boolean or null")

        if border_style is not None:
            if not isinstance(border_style, str):
                _log("error", "VALIDATION_ERROR", {"field": "border_style"})
                return _err("VALIDATION_ERROR", "border_style must be string or null")
            if border_style not in ("none", "single", "double", "thick"):
                _log("error", "VALIDATION_ERROR", {"field": "border_style"})
                return _err("VALIDATION_ERROR", "unsupported border_style", supported=["none", "single", "double", "thick"])

        docs = _load("documents.json")
        blocks = _load("document_blocks.json")
        formats = _load("table_formats.json")
        if not isinstance(docs, list): docs = []
        if not isinstance(blocks, list): blocks = []
        if not isinstance(formats, list): formats = []

        doc = _find_doc(docs, full_path)
        if not doc or doc.get("status") == "deleted":
            _log("error", "NOT_FOUND", {"filename": full_path})
            return _err("NOT_FOUND", "document not found", filename=full_path)

        doc_id = doc.get("id")
        active_tables = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc_id and b.get("status") == "active" and b.get("block_type") == "table"]
        active_tables.sort(key=lambda x: (x.get("ordinal") if isinstance(x.get("ordinal"), int) else 10**9, x.get("id") or ""))

        if table_index >= len(active_tables):
            _log("error", "NOT_FOUND", {"filename": full_path, "table_index": table_index})
            return _err("NOT_FOUND", "table_index does not exist", filename=full_path, table_index=table_index)

        table_block = active_tables[table_index]
        table_block_id = table_block.get("id")
        rows = table_block.get("table_rows")
        cols = table_block.get("table_cols")
        if not isinstance(rows, int) or rows < 1 or not isinstance(cols, int) or cols < 1:
            _log("error", "CONFLICT", {"rule": "table block missing valid dimensions", "table_block_id": table_block_id})
            return _err("CONFLICT", "table block does not have valid row/col dimensions", table_block_id=table_block_id)

        if shading is not None:
            if not isinstance(shading, list):
                _log("error", "VALIDATION_ERROR", {"field": "shading"})
                return _err("VALIDATION_ERROR", "shading must be a 2D array of strings or null")
            if len(shading) != rows:
                _log("error", "VALIDATION_ERROR", {"field": "shading", "rule": "match rows"})
                return _err("VALIDATION_ERROR", "shading row count must match table_rows", table_rows=rows, shading_rows=len(shading))
            for r in shading:
                if not isinstance(r, list) or len(r) != cols:
                    _log("error", "VALIDATION_ERROR", {"field": "shading", "rule": "match cols"})
                    return _err("VALIDATION_ERROR", "shading column count must match table_cols", table_cols=cols)
                for c in r:
                    if not isinstance(c, str):
                        _log("error", "VALIDATION_ERROR", {"field": "shading"})
                        return _err("VALIDATION_ERROR", "shading cells must be strings")

        # Upsert active format for this table_block_id (unique where active)
        existing = None
        for tf in formats:
            if isinstance(tf, dict) and tf.get("table_block_id") == table_block_id and tf.get("status") == "active":
                existing = tf
                break

        if existing is None:
            tf_row = {
                "id": _gen_id("owd_tbf"),
                "document_id": doc_id,
                "table_block_id": table_block_id,
                "has_header_row": has_header_row,
                "border_style": border_style,
                "shading": shading,
                "status": "active",
                "created_at": now,
                "updated_at": now
            }
            formats.append(tf_row)
        else:
            if has_header_row is not None:
                existing["has_header_row"] = has_header_row
            if border_style is not None:
                existing["border_style"] = border_style
            if shading is not None:
                existing["shading"] = shading
            existing["updated_at"] = now
            tf_row = existing

        cv = doc.get("content_version")
        if not isinstance(cv, int) or cv < 1:
            cv = 1
        doc["content_version"] = cv + 1
        doc["updated_at"] = now

        _save("table_formats.json", formats)
        _save("documents.json", docs)

        _log("ok", None, {"filename": full_path, "document_id": doc_id, "table_block_id": table_block_id, "table_index": table_index})
        return {
            "document_id": doc_id,
            "filename": doc.get("full_path"),
            "content_version": doc.get("content_version"),
            "table_index": table_index,
            "table_block_id": table_block_id,
            "table_format": tf_row
        }
    except Exception as e:
        _log("error", "CONFLICT", {"exception": str(e)})
        return _err("CONFLICT", "internal error")

def protect_document(filename, password, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request logging (best-effort; must not throw)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    log_row = {
        "id": f"req_{secrets.token_hex(12)}",
        "endpoint": "protect_document",
        "timestamp": now,
        "status": "error",
        "latency_ms": None,
    }

    def _finish(resp, status):
        try:
            log_row["status"] = status
            log_row["latency_ms"] = int((time.time() - t0) * 1000)
            logs.append(log_row)
            _save("request_logs.json", logs)
        except Exception:
            pass
        return resp

    # Validate inputs
    if not isinstance(filename, str) or not filename.strip():
        return _finish(_err("VALIDATION_ERROR", "filename must be a non-empty string"), "error")
    if not isinstance(password, str) or password == "":
        return _finish(_err("VALIDATION_ERROR", "password must be a non-empty string"), "error")

    def _normalize_full_path(p):
        p = p.strip()
        if not p.lower().endswith(".docx"):
            p = p + ".docx"
        p = p.replace("\\", "/")
        while "//" in p:
            p = p.replace("//", "/")
        if not p.startswith("/"):
            p = "/" + p
        return p

    full_path = _normalize_full_path(filename)

    documents = _load("documents.json")
    if not isinstance(documents, list):
        documents = []

    doc = None
    for d in documents:
        if isinstance(d, dict) and d.get("full_path") == full_path:
            doc = d
            break

    if not doc:
        return _finish(_err("NOT_FOUND", "Document not found", filename=full_path), "error")

    if doc.get("status") == "deleted":
        return _finish(_err("NOT_FOUND", "Document not found", filename=full_path), "error")

    if doc.get("status") == "protected":
        return _finish(_err("CONFLICT", "Document is already protected", filename=full_path), "error")

    # Lifecycle transition enforcement
    allowed = {
        "active": ["protected", "archived", "deleted"],
        "protected": ["active", "archived", "deleted"],
        "archived": ["active", "deleted"],
        "deleted": [],
    }
    cur = doc.get("status")
    if cur not in allowed or "protected" not in allowed.get(cur, []):
        return _finish(_err("INVALID_TRANSITION", f"Cannot transition document from {cur} to protected"), "error")

    # Generate password hash (store only hash; algorithm modeled)
    # Using scrypt (stdlib) with salt; stored in a self-describing string.
    salt = secrets.token_bytes(16)
    dk = hashlib.scrypt(password.encode("utf-8"), salt=salt, n=2**14, r=8, p=1, dklen=32)
    stored = "scrypt$" + salt.hex() + "$" + dk.hex()

    doc["status"] = "protected"
    doc["protected_password_hash"] = stored
    doc["protection_algorithm"] = "scrypt"
    doc["updated_at"] = now

    # Increment content_version on mutating tools
    try:
        cv = int(doc.get("content_version", 0))
    except Exception:
        cv = 0
    if cv < 1:
        cv = 1
    doc["content_version"] = cv + 1

    # Validate constraints relevant to mutation
    fn = doc.get("filename")
    if doc["status"] in ("active", "protected", "archived"):
        if not isinstance(fn, str) or not fn.lower().endswith(".docx"):
            return _finish(_err("VALIDATION_ERROR", "filename must end with '.docx' for non-deleted documents"), "error")
    if doc["status"] == "protected" and not doc.get("protected_password_hash"):
        return _finish(_err("VALIDATION_ERROR", "protected documents must have a protected_password_hash"), "error")

    _save("documents.json", documents)
    return _finish({"document": doc}, "ok")

def unprotect_document(filename, password, **_extra):
    import json, os, datetime, time, hashlib, hmac, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

