    if not isinstance(logs, list):
        logs = []
    log_row = {
        "id": f"req_{secrets.token_hex(12)}",
        "endpoint": "unprotect_document",
        "timestamp": now,
        "status": "error",
        "latency_ms": None,
    }

    def _finish(resp, status):
        try:
            log_row["status"] = status
            log_row["latency_ms"] = int((time.time() - t0) * 1000)
            logs.append(log_row)
            _save("request_logs.json", logs)
        except Exception:
            pass
        return resp

    if not isinstance(filename, str) or not filename.strip():
        return _finish(_err("VALIDATION_ERROR", "filename must be a non-empty string"), "error")
    if not isinstance(password, str) or password == "":
        return _finish(_err("VALIDATION_ERROR", "password must be a non-empty string"), "error")

    def _normalize_full_path(p):
        p = p.strip()
        if not p.lower().endswith(".docx"):
            p = p + ".docx"
        p = p.replace("\\", "/")
        while "//" in p:
            p = p.replace("//", "/")
        if not p.startswith("/"):
            p = "/" + p
        return p

    full_path = _normalize_full_path(filename)

    documents = _load("documents.json")
    if not isinstance(documents, list):
        documents = []

    doc = None
    for d in documents:
        if isinstance(d, dict) and d.get("full_path") == full_path:
            doc = d
            break

    if not doc:
        return _finish(_err("NOT_FOUND", "Document not found", filename=full_path), "error")

    if doc.get("status") == "deleted":
        return _finish(_err("NOT_FOUND", "Document not found", filename=full_path), "error")

    if doc.get("status") != "protected":
        return _finish(_err("CONFLICT", "Document is not protected", filename=full_path), "error")

    # Verify password against stored hash
    stored = doc.get("protected_password_hash")
    if not isinstance(stored, str) or "$" not in stored:
        # Corrupt protection state; treat as unauthorized/forbidden to avoid unlocking without proof
        return _finish(_err("UNAUTHORIZED", "Document protection state is invalid"), "error")

    ok = False
    try:
        parts = stored.split("$", 2)
        algo = parts[0]
        salt_hex = parts[1]
        hash_hex = parts[2]
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(hash_hex)

        if algo == "scrypt":
            dk = hashlib.scrypt(password.encode("utf-8"), salt=salt, n=2**14, r=8, p=1, dklen=len(expected))
