    # Lifecycle transition
    allowed = {
        "active": ["protected", "archived", "deleted"],
        "protected": ["active", "archived", "deleted"],
        "archived": ["active", "deleted"],
        "deleted": [],
    }
    if "active" not in allowed.get("protected", []):
        return _finish(_err("INVALID_TRANSITION", "Cannot transition document from protected to active"), "error")

    doc["status"] = "active"
    doc["protected_password_hash"] = None
    doc["protection_algorithm"] = None
    doc["updated_at"] = now

    try:
        cv = int(doc.get("content_version", 0))
    except Exception:
        cv = 0
    if cv < 1:
        cv = 1
    doc["content_version"] = cv + 1

    _save("documents.json", documents)
    return _finish({"document": doc}, "ok")

