        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        if "\x00" in s or re.match(r"^[a-zA-Z]+://", s):
            return None
        s = re.sub(r"/+", "/", s)
        if s.startswith("./"):
            s = s[2:]
        if not s.lower().endswith(".docx"):
            s += ".docx"
        return s

    def _cands(norm_full):
        if not norm_full:
            return []
        xs = [norm_full]
        if norm_full.startswith("/"):
            xs.append(norm_full.lstrip("/"))
        else:
            xs.append("/" + norm_full)
        out, seen = [], set()
        for x in xs:
            if x not in seen:
                seen.add(x); out.append(x)
        return out

    def _find_doc(docs, norm_full):
        for c in _cands(norm_full):
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    try:
        full_path = _norm_docx_full_path(filename)
        if full_path is None:
            _log("error", "VALIDATION_ERROR", {"field": "filename"})
            return _err("VALIDATION_ERROR", "filename must be a non-empty string (.docx will be appended if missing)")

        if not isinstance(paragraph_index, int) or paragraph_index < 0:
            _log("error", "VALIDATION_ERROR", {"field": "paragraph_index"})
            return _err("VALIDATION_ERROR", "paragraph_index must be an integer >= 0")

        docs = _load("documents.json")
        blocks = _load("document_blocks.json")
        if not isinstance(docs, list): docs = []
        if not isinstance(blocks, list): blocks = []

        doc = _find_doc(docs, full_path)
        if not doc or doc.get("status") == "deleted":
            _log("error", "NOT_FOUND", {"filename": full_path})
            return _err("NOT_FOUND", "document not found", filename=full_path)

        doc_id = doc.get("id")
        active_ph = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc_id and b.get("status") == "active" and b.get("block_type") in ("paragraph", "heading")]
        active_ph.sort(key=lambda x: (x.get("ordinal") if isinstance(x.get("ordinal"), int) else 10**9, x.get("id") or ""))

        if paragraph_index >= len(active_ph):
            _log("error", "VALIDATION_ERROR", {"paragraph_index": paragraph_index, "max": max(len(active_ph) - 1, -1)})
            return _err("VALIDATION_ERROR", "paragraph_index is outside the document’s paragraph range", paragraph_count=len(active_ph), paragraph_index=paragraph_index)

        block = active_ph[paragraph_index]
        txt = block.get("text")
        if not isinstance(txt, str):
            txt = ""

        _log("ok", None, {"filename": full_path, "document_id": doc_id, "block_id": block.get("id"), "paragraph_index": paragraph_index})
        return {
            "document_id": doc_id,
            "filename": doc.get("full_path"),
            "paragraph_index": paragraph_index,
            "block_id": block.get("id"),
            "text": txt
        }
    except Exception as e:
        _log("error", "CONFLICT", {"exception": str(e)})
        return _err("CONFLICT", "internal error")

def find_text_in_document(filename, text_to_find, match_case=None, whole_word=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({
                "id": f"req_{secrets.token_hex(12)}",
                "endpoint": "find_text_in_document",
                "timestamp": now,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    def _parse_iso_z(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        s = re.sub(r"/+", "/", s)
        if not s.lower().endswith(".docx"):
            s = s + ".docx"
        if s.startswith("./"):
            s = s[2:]
        return s

    def _find_doc_by_any_path(docs, norm_full):
        candidates = [norm_full]
        if norm_full.startswith("/"):
            candidates.append(norm_full.lstrip("/"))
        else:
            candidates.append("/" + norm_full)
        for c in candidates:
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    if not isinstance(filename, str) or not filename.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filename must be a non-empty string")
    if not isinstance(text_to_find, str) or text_to_find == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "text_to_find must be a non-empty string")

    if match_case is None:
        match_case = True
    if whole_word is None:
        whole_word = False
    if not isinstance(match_case, bool) or not isinstance(whole_word, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "match_case and whole_word must be booleans")

    docs = _load("documents.json")
    blocks = _load("document_blocks.json")
    if not isinstance(docs, list): docs = []
    if not isinstance(blocks, list): blocks = []

    full_path = _norm_docx_full_path(filename)
    doc = _find_doc_by_any_path(docs, full_path)
    if not doc or doc.get("status") == "deleted":
        _log("error", "NOT_FOUND", {"filename": full_path})
        return _err("NOT_FOUND", "document not found", filename=full_path)

    doc_id = doc.get("id")

    # Use cached_full_text if "recent enough"; define recent as within 5 minutes
    cached_text = doc.get("cached_full_text")
    last_idx = _parse_iso_z(doc.get("last_indexed_at"))
    is_fresh = False
    if last_idx is not None:
        try:
            is_fresh = (datetime.datetime.utcnow() - last_idx).total_seconds() <= 300
        except Exception:
            is_fresh = False

    if not (isinstance(cached_text, str) and is_fresh):
        active_blocks = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc_id and b.get("status") == "active"]
        active_blocks.sort(key=lambda x: (x.get("ordinal", 0), x.get("created_at", "")))
        texts = []
        for b in active_blocks:
            if b.get("block_type") in ("paragraph", "heading"):
                t = b.get("text")
                if isinstance(t, str) and t != "":
                    texts.append(t)
            elif b.get("block_type") == "table":
                td = b.get("table_data")
                if isinstance(td, list):
                    for r in td:
                        if isinstance(r, list):
                            for c in r:
                                if isinstance(c, str) and c != "":
                                    texts.append(c)
        cached_text = "\n".join(texts)
        doc["cached_full_text"] = cached_text
        doc["last_indexed_at"] = now
        doc["updated_at"] = doc.get("updated_at") or now
        _save("documents.json", docs)

    haystack = cached_text if isinstance(cached_text, str) else ""
    needle = text_to_find
    if not match_case:
        haystack_cmp = haystack.lower()
        needle_cmp = needle.lower()
    else:
        haystack_cmp = haystack
        needle_cmp = needle

    if whole_word:
        pattern = r"\b" + re.escape(needle_cmp) + r"\b"
        matches_iter = re.finditer(pattern, haystack_cmp)
        matches = [{"start": m.start(), "end": m.end(), "match": haystack[m.start():m.end()]} for m in matches_iter]
    else:
        matches = []
        start = 0
        while True:
            idx = haystack_cmp.find(needle_cmp, start)
            if idx == -1:
                break
            matches.append({"start": idx, "end": idx + len(needle), "match": haystack[idx:idx + len(needle)]})
            start = idx + (1 if len(needle) == 0 else len(needle))

    # Provide lightweight "locations": also search per-block to produce structural positions
    active_blocks = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc_id and b.get("status") == "active" and b.get("block_type") in ("paragraph", "heading")]
    active_blocks.sort(key=lambda x: (x.get("ordinal", 0), x.get("created_at", "")))
    locations = []
    for b in active_blocks:
        txt = b.get("text") if isinstance(b.get("text"), str) else ""
        txt_cmp = txt if match_case else txt.lower()
        needle_cmp2 = needle if match_case else needle.lower()
        if whole_word:
            patt = r"\b" + re.escape(needle_cmp2) + r"\b"
            for m in re.finditer(patt, txt_cmp):
                locations.append({"block_id": b.get("id"), "block_type": b.get("block_type"), "ordinal": b.get("ordinal"), "start_pos": m.start(), "end_pos": m.end()})
        else:
            s = 0
            while True:
                j = txt_cmp.find(needle_cmp2, s)
                if j == -1:
                    break
                locations.append({"block_id": b.get("id"), "block_type": b.get("block_type"), "ordinal": b.get("ordinal"), "start_pos": j, "end_pos": j + len(needle)})
                s = j + (1 if len(needle) == 0 else len(needle))

    _log("success")
    return {
        "document_id": doc_id,
        "filename": doc.get("full_path"),
        "query": {"text_to_find": text_to_find, "match_case": match_case, "whole_word": whole_word},
        "match_count": len(matches),
        "matches": matches,
        "locations": locations,
        "used_cache": bool(is_fresh and isinstance(doc.get("cached_full_text"), str)),
    }

def convert_to_pdf(filename, output_filename=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
