    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    endpoint = "convert_to_pdf"

    def _log(status, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        if "\x00" in s or re.match(r"^[a-zA-Z]+://", s):
            return None
        s = re.sub(r"/+", "/", s)
        if s.startswith("./"):
            s = s[2:]
        if not s.lower().endswith(".docx"):
            s += ".docx"
        return s

    def _norm_pdf_path(p, src_full):
        if p is None:
            base = src_full[:-5] if src_full.lower().endswith(".docx") else src_full
            return base + ".pdf"
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        if "\x00" in s or re.match(r"^[a-zA-Z]+://", s):
            return None
        s = re.sub(r"/+", "/", s)
        if s.startswith("./"):
            s = s[2:]
        if not s.lower().endswith(".pdf"):
            s += ".pdf"
        return s

    def _cands(norm_full):
        if not norm_full:
            return []
        xs = [norm_full]
        if norm_full.startswith("/"):
            xs.append(norm_full.lstrip("/"))
        else:
            xs.append("/" + norm_full)
        out, seen = [], set()
        for x in xs:
            if x not in seen:
                seen.add(x); out.append(x)
        return out

    def _find_doc(docs, norm_full):
        for c in _cands(norm_full):
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    try:
        src_full = _norm_docx_full_path(filename)
        if src_full is None:
            _log("error", "VALIDATION_ERROR", {"field": "filename"})
            return _err("VALIDATION_ERROR", "filename must be a non-empty string (.docx will be appended if missing)")

        docs = _load("documents.json")
        if not isinstance(docs, list): docs = []
        doc = _find_doc(docs, src_full)
        if not doc or doc.get("status") == "deleted":
            _log("error", "NOT_FOUND", {"filename": src_full})
            return _err("NOT_FOUND", "document not found", filename=src_full)

        out_full = _norm_pdf_path(output_filename, src_full)
        if out_full is None:
            _log("error", "VALIDATION_ERROR", {"field": "output_filename"})
            return _err("VALIDATION_ERROR", "output_filename is invalid")

        # Create/overwrite artifact on disk (best-effort; must not crash)
        # Treat paths as server-rooted relative; write to /mnt/owd/exports by default when not absolute.
        if out_full.startswith("/"):
            out_path = out_full
        else:
            out_path = os.path.join("/mnt/owd/exports", out_full)
        out_dir = os.path.dirname(out_path) or "/mnt/owd/exports"
        try:
            os.makedirs(out_dir, exist_ok=True)
        except OSError:
            _log("error", "CONFLICT", {"rule": "cannot create output directory", "output_path": out_path})
            return _err("CONFLICT", "cannot create output directory", output_path=out_path)

        content = f"%PDF-1.4\n% Office Word Document Server export\n% source: {doc.get('full_path')}\n% exported_at: {now}\n"
        try:
            with open(out_path, "wb") as f:
                f.write(content.encode("utf-8"))
        except OSError:
            _log("error", "CONFLICT", {"rule": "cannot write output file", "output_path": out_path})
            return _err("CONFLICT", "cannot write output file", output_path=out_path)

        # Record export metadata (implementation-specific extension fields allowed)
        doc["updated_at"] = now
        doc["last_exported_pdf_path"] = out_full
        doc["last_exported_pdf_at"] = now
        _save("documents.json", docs)

        _log("ok", None, {"filename": src_full, "output_filename": out_full, "output_path": out_path, "document_id": doc.get("id")})
        return {
            "document_id": doc.get("id"),
            "filename": doc.get("full_path"),
            "output_filename": out_full,
            "output_path": out_path,
        }
    except Exception as e:
        _log("error", "CONFLICT", {"exception": str(e)})
        return _err("CONFLICT", "internal error")

def update_document_info(filename, title=None, author=None, status=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, detail=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}_{hashlib.sha256((endpoint+_now()).encode('utf-8')).hexdigest()[:10]}",
                    "endpoint": endpoint,
                    "status": status_code,
                    "detail": detail,
                    "timestamp": _now(),
                    "latency_ms": int((time.time() - t0) * 1000),
                }
            )
            _save("request_logs.json", logs)
        except Exception:
            return

    def _norm_docx_path(p):
        if not isinstance(p, str):
            return None
        p = p.strip()
        if not p:
            return None
        if not p.lower().endswith(".docx"):
            p = p + ".docx"
        return os.path.normpath(p)

    try:
        fp = _norm_docx_path(filename)
        if fp is None:
            _log("update_document_info", "VALIDATION_ERROR", "filename must be a non-empty string")
            return _err("VALIDATION_ERROR", "filename must be a non-empty string")

        if title is not None and not isinstance(title, str):
            _log("update_document_info", "VALIDATION_ERROR", "title must be string or null")
            return _err("VALIDATION_ERROR", "title must be a string or null")

        if author is not None and not isinstance(author, str):
            _log("update_document_info", "VALIDATION_ERROR", "author must be string or null")
            return _err("VALIDATION_ERROR", "author must be a string or null")

        if status is not None:
            if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
                _log("update_document_info", "VALIDATION_ERROR", "invalid status")
                return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted (or null)")

        docs = _load("documents.json")
        if not isinstance(docs, list):
            docs = []
        doc = next((d for d in docs if isinstance(d, dict) and d.get("full_path") == fp), None)
        if doc is None:
            _log("update_document_info", "NOT_FOUND", "document not found")
            return _err("NOT_FOUND", "Document not found")

        if doc.get("status") == "deleted":
            _log("update_document_info", "CONFLICT", "cannot update deleted document")
            return _err("CONFLICT", "Document is deleted")

        mutated = False
        now = _now()

        # Metadata updates
        if title is not None and title != doc.get("title"):
            doc["title"] = title
            mutated = True
        if author is not None and author != doc.get("author"):
            doc["author"] = author
            mutated = True

        # Status transitions: protected transitions are not allowed here
        if status is not None and status != doc.get("status"):
            cur = doc.get("status")
            if cur == "protected":
                _log("update_document_info", "CONFLICT", "protected transitions require dedicated tools")
                return _err("CONFLICT", "Use protect_document/unprotect_document for protected transitions")

            allowed = {
                "active": {"archived", "deleted"},
                "archived": {"active", "deleted"},
                "protected": set(),  # handled above
                "deleted": set(),
            }
            if status not in allowed.get(cur, set()):
                _log("update_document_info", "INVALID_TRANSITION", f"{cur} -> {status}")
                return _err("INVALID_TRANSITION", f"Illegal status transition: {cur} -> {status}")

            # Enforce constraints: non-deleted must have .docx for active/archived
            if status in ("active", "archived"):
                if not isinstance(doc.get("filename"), str) or not doc["filename"].lower().endswith(".docx"):
                    _log("update_document_info", "VALIDATION_ERROR", "filename must end with .docx")
                    return _err("VALIDATION_ERROR", "filename must end with '.docx' for non-deleted status")

            if status == "deleted":
                # cascade soft delete of related records: set status='deleted'/'superseded' as appropriate
                blocks = _load("document_blocks.json")
                spans = _load("text_spans.json")
                styles = _load("styles.json")
                notes = _load("notes.json")
                tfmts = _load("table_formats.json")

                if isinstance(blocks, list):
                    for b in blocks:
                        if isinstance(b, dict) and b.get("document_id") == doc.get("id") and b.get("status") == "active":
                            b["status"] = "deleted"
                            b["updated_at"] = now
                    _save("document_blocks.json", blocks)

                if isinstance(spans, list):
                    for s in spans:
                        if isinstance(s, dict) and s.get("document_id") == doc.get("id") and s.get("status") == "active":
                            s["status"] = "superseded"
                            s["updated_at"] = now
                    _save("text_spans.json", spans)

                if isinstance(styles, list):
                    for st in styles:
                        if isinstance(st, dict) and st.get("document_id") == doc.get("id") and st.get("status") == "active":
                            st["status"] = "deleted"
                            st["updated_at"] = now
                    _save("styles.json", styles)

                if isinstance(notes, list):
                    for n in notes:
                        if isinstance(n, dict) and n.get("document_id") == doc.get("id") and n.get("status") == "active":
                            n["status"] = "deleted"
                            n["updated_at"] = now
                    _save("notes.json", notes)

                if isinstance(tfmts, list):
                    for tf in tfmts:
                        if isinstance(tf, dict) and tf.get("document_id") == doc.get("id") and tf.get("status") == "active":
                            tf["status"] = "deleted"
                            tf["updated_at"] = now
                    _save("table_formats.json", tfmts)

            doc["status"] = status
            # Constraints: protected_password_hash must be null when not protected
            if status != "protected":
                doc["protected_password_hash"] = None
                doc["protection_algorithm"] = None
            mutated = True

        if not mutated:
            _log("update_document_info", "NOT_FOUND", "no changes requested")
            return _err("NOT_FOUND", "No changes applied (fields unchanged)")

        doc["updated_at"] = now
        _save("documents.json", docs)
        _log("update_document_info", "OK", None)
        return {"document": doc}
    except Exception as e:
        _log("update_document_info", "VALIDATION_ERROR", f"unexpected: {type(e).__name__}")
        return _err("VALIDATION_ERROR", "Invalid request")

def archive_document(filename, **_extra):
    import json, os, datetime, time, re, secrets
