    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "archive_document"

    def _log(status, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        if "\x00" in s or re.match(r"^[a-zA-Z]+://", s):
            return None
        s = re.sub(r"/+", "/", s)
        if s.startswith("./"):
            s = s[2:]
        if not s.lower().endswith(".docx"):
            s += ".docx"
        return s

    def _cands(norm_full):
        if not norm_full:
            return []
        xs = [norm_full]
        if norm_full.startswith("/"):
            xs.append(norm_full.lstrip("/"))
        else:
            xs.append("/" + norm_full)
        out, seen = [], set()
        for x in xs:
            if x not in seen:
                seen.add(x); out.append(x)
        return out

    def _find_doc(docs, norm_full):
        for c in _cands(norm_full):
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    try:
        full_path = _norm_docx_full_path(filename)
        if full_path is None:
            _log("error", "VALIDATION_ERROR", {"field": "filename"})
            return _err("VALIDATION_ERROR", "filename must be a non-empty string (.docx will be appended if missing)")

        docs = _load("documents.json")
        if not isinstance(docs, list): docs = []

        doc = _find_doc(docs, full_path)
        if not doc:
            _log("error", "NOT_FOUND", {"filename": full_path})
            return _err("NOT_FOUND", "document not found", filename=full_path)

        if doc.get("status") == "deleted":
            _log("error", "CONFLICT", {"rule": "cannot archive deleted document"})
            return _err("CONFLICT", "cannot archive a deleted document", filename=doc.get("full_path"))

        cur = doc.get("status")
        allowed = {"active", "protected", "archived", "deleted"}
        if cur not in allowed:
            _log("error", "CONFLICT", {"rule": "unknown status", "status": cur})
            return _err("CONFLICT", "document has unknown status", status=cur)

        if cur == "archived":
            _log("error", "INVALID_TRANSITION", {"from": cur, "to": "archived"})
            return _err("INVALID_TRANSITION", "document is already archived", filename=doc.get("full_path"))

        if cur not in ("active", "protected"):
            _log("error", "INVALID_TRANSITION", {"from": cur, "to": "archived"})
            return _err("INVALID_TRANSITION", "cannot archive from current status", from_status=cur, to_status="archived")

        doc["status"] = "archived"
        # Enforce constraint: status!='protected' implies protected_password_hash is null
        doc["protected_password_hash"] = None
        doc["protection_algorithm"] = None
        doc["updated_at"] = now

        _save("documents.json", docs)

        _log("ok", None, {"filename": full_path, "document_id": doc.get("id"), "from_status": cur, "to_status": "archived"})
        return {"document": doc}
    except Exception as e:
        _log("error", "CONFLICT", {"exception": str(e)})
        return _err("CONFLICT", "internal error")

def restore_archived_document(filename, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, detail=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}_{hashlib.sha256((endpoint+_now()).encode('utf-8')).hexdigest()[:10]}",
                    "endpoint": endpoint,
                    "status": status_code,
                    "detail": detail,
                    "timestamp": _now(),
                    "latency_ms": int((time.time() - t0) * 1000),
                }
            )
            _save("request_logs.json", logs)
        except Exception:
            return

    def _norm_docx_path(p):
        if not isinstance(p, str):
            return None
        p = p.strip()
        if not p:
            return None
        if not p.lower().endswith(".docx"):
            p = p + ".docx"
        return os.path.normpath(p)

    try:
        fp = _norm_docx_path(filename)
        if fp is None:
            _log("restore_archived_document", "VALIDATION_ERROR", "filename must be a non-empty string")
            return _err("VALIDATION_ERROR", "filename must be a non-empty string")

        docs = _load("documents.json")
        if not isinstance(docs, list):
            docs = []
        doc = next((d for d in docs if isinstance(d, dict) and d.get("full_path") == fp), None)
        if doc is None:
            _log("restore_archived_document", "NOT_FOUND", "document not found")
            return _err("NOT_FOUND", "Document not found")

        cur = doc.get("status")
        if cur == "deleted":
            _log("restore_archived_document", "CONFLICT", "document is deleted")
            return _err("CONFLICT", "Document is deleted")
        if cur != "archived":
            _log("restore_archived_document", "CONFLICT", "not archived")
            return _err("CONFLICT", "Document is not archived")

        # archived -> active allowed
        doc["status"] = "active"
        doc["updated_at"] = _now()
        _save("documents.json", docs)

        _log("restore_archived_document", "OK", None)
        return {"document": doc}
    except Exception as e:
        _log("restore_archived_document", "VALIDATION_ERROR", f"unexpected: {type(e).__name__}")
        return _err("VALIDATION_ERROR", "Invalid request")

def delete_document(filename, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({
                "id": f"req_{secrets.token_hex(12)}",
                "endpoint": "delete_document",
                "timestamp": now,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        s = re.sub(r"/+", "/", s)
        if not s.lower().endswith(".docx"):
            s = s + ".docx"
        if s.startswith("./"):
            s = s[2:]
        return s

    def _find_doc_by_any_path(docs, norm_full):
        candidates = [norm_full]
        if norm_full.startswith("/"):
            candidates.append(norm_full.lstrip("/"))
        else:
            candidates.append("/" + norm_full)
        for c in candidates:
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    if not isinstance(filename, str) or not filename.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filename must be a non-empty string")

    docs = _load("documents.json")
    if not isinstance(docs, list): docs = []

    full_path = _norm_docx_full_path(filename)
    doc = _find_doc_by_any_path(docs, full_path)
    if not doc:
        _log("error", "NOT_FOUND", {"filename": full_path})
        return _err("NOT_FOUND", "document not found", filename=full_path)

    if doc.get("status") == "deleted":
        _log("error", "CONFLICT", {"status": "deleted"})
        return _err("CONFLICT", "document is already deleted")

    # Enforce lifecycle transition legality
    allowed = {"active": ["protected", "archived", "deleted"], "protected": ["active", "archived", "deleted"], "archived": ["active", "deleted"], "deleted": []}
    cur = doc.get("status")
    if cur not in allowed or "deleted" not in allowed.get(cur, []):
        _log("error", "INVALID_TRANSITION", {"from": cur, "to": "deleted"})
        return _err("INVALID_TRANSITION", "cannot transition document to deleted from current status", from_status=cur, to_status="deleted")

    doc["status"] = "deleted"
    doc["updated_at"] = now
    doc["cached_full_text"] = None
    doc["cached_outline"] = None
    doc["last_indexed_at"] = None
    # For constraints: status!='protected' implies protected_password_hash is null
    doc["protected_password_hash"] = None
    doc["protection_algorithm"] = None

    _save("documents.json", docs)

    _log("success")
    return {"document": doc}

def get_document_blocks(filename, block_type=None, status="active", page=1, page_size=50, **_extra):
    import json, os, datetime, time, re, secrets, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0409000" if __import__("os").path.isdir("./environment_mix/0409000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "get_document_blocks"

    def _log(status_s, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{secrets.token_hex(12)}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _norm_docx_full_path(p):
        if not isinstance(p, str) or not p.strip():
            return None
        s = p.strip().replace("\\", "/")
        if "\x00" in s or re.match(r"^[a-zA-Z]+://", s):
            return None
        s = re.sub(r"/+", "/", s)
        if s.startswith("./"):
            s = s[2:]
        if not s.lower().endswith(".docx"):
            s += ".docx"
        return s

    def _cands(norm_full):
        if not norm_full:
            return []
        xs = [norm_full]
        if norm_full.startswith("/"):
            xs.append(norm_full.lstrip("/"))
        else:
            xs.append("/" + norm_full)
        out, seen = [], set()
        for x in xs:
            if x not in seen:
                seen.add(x); out.append(x)
        return out

    def _find_doc(docs, norm_full):
        for c in _cands(norm_full):
            for d in docs:
                if isinstance(d, dict) and d.get("full_path") == c:
                    return d
        return None

    try:
        full_path = _norm_docx_full_path(filename)
        if full_path is None:
            _log("error", "VALIDATION_ERROR", {"field": "filename"})
            return _err("VALIDATION_ERROR", "filename must be a non-empty string (.docx will be appended if missing)")

        if block_type is not None:
            if not isinstance(block_type, str) or block_type not in ("paragraph", "heading", "table", "picture", "page_break"):
                _log("error", "VALIDATION_ERROR", {"field": "block_type"})
                return _err("VALIDATION_ERROR", "block_type is invalid", allowed=["paragraph", "heading", "table", "picture", "page_break", None])

        if status not in ("active", "deleted", "all"):
            _log("error", "VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, deleted, all")

        if not isinstance(page, int) or page < 1:
            _log("error", "VALIDATION_ERROR", {"field": "page"})
            return _err("VALIDATION_ERROR", "page must be an integer >= 1")
        if not isinstance(page_size, int) or not (1 <= page_size <= 200):
            _log("error", "VALIDATION_ERROR", {"field": "page_size"})
            return _err("VALIDATION_ERROR", "page_size must be between 1 and 200")

        docs = _load("documents.json")
        blocks = _load("document_blocks.json")
        if not isinstance(docs, list): docs = []
        if not isinstance(blocks, list): blocks = []

        doc = _find_doc(docs, full_path)
        if not doc or doc.get("status") == "deleted":
            _log("error", "NOT_FOUND", {"filename": full_path})
            return _err("NOT_FOUND", "document not found", filename=full_path)

        if doc.get("status") == "protected":
            _log("error", "CONFLICT", {"filename": full_path})
            return _err("CONFLICT", "document is protected and disallows block inspection", filename=full_path)

        doc_id = doc.get("id")
        rows = [b for b in blocks if isinstance(b, dict) and b.get("document_id") == doc_id]
        if block_type is not None:
            rows = [b for b in rows if b.get("block_type") == block_type]
        if status != "all":
            rows = [b for b in rows if b.get("status") == status]

        rows.sort(key=lambda x: (x.get("ordinal") if isinstance(x.get("ordinal"), int) else 10**9, x.get("id") or ""))

        total = len(rows)
        start = (page - 1) * page_size
        end = start + page_size
        page_rows = rows[start:end]
        has_more = end < total
        total_pages = int(math.ceil(total / page_size)) if page_size else 1

        _log("ok", None, {"filename": full_path, "document_id": doc_id, "total": total, "page": page, "page_size": page_size})
        return {
            "filename": doc.get("full_path"),
            "document_id": doc_id,
            "content_version": doc.get("content_version"),
            "page": page,
            "page_size": page_size,
            "total": total,
            "total_pages": total_pages,
            "has_more": has_more,
            "blocks": page_rows
        }
    except Exception as e:
        _log("error", "CONFLICT", {"exception": str(e)})
        return _err("CONFLICT", "internal error")
